// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        uint256 bal = 1 ether;
        vm.deal(address(c), bal);
        vm.prank(caller);
        try c.withdrawAll(caller) { } catch { }
        bool drainedByNonOwner = address(c).balance == 0;
        assertTrue(!drainedByNonOwner);
    }
}
